    fun getDistrictsForGovernorate(govName: String?): List<String> {
        if (govName.isNullOrBlank()) return emptyList()
        val match = governorates.firstOrNull {
            it.nameAr.equals(govName, ignoreCase = true) ||
            it.nameEn.equals(govName, ignoreCase = true) ||
            it.id.equals(govName, ignoreCase = true)
        }
        return match?.popularDistricts ?: emptyList()
    }
